; ==========================================================
; DrawSprite: dibuja un bitmap en modo 0013h (320x200, 256 col)
;
; Parámetros (se empujan en este orden antes del CALL):
;   push offset spriteData   (etiqueta db del bitmap)
;   push posY                (word, ej. iposyF)
;   push posX                (word, ej. iposxF)
;   push height               (word, ej. KYF)
;   push width                (word, ej. KXF)   <-- éste va último
;   call DrawSprite
;
; El color 0 dentro del bitmap se trata como transparente
; (no se dibuja), igual que hacía tu código original.
; ==========================================================
DrawSprite PROC
    push bp
    mov bp, sp
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es

    ; [bp+4]  = width
    ; [bp+6]  = height
    ; [bp+8]  = posx
    ; [bp+10] = posy
    ; [bp+12] = offset del bitmap

    mov ax, 0A000h
    mov es, ax

    ; DI = posy*320 + posx
    mov ax, [bp+10]
    mov bx, 320
    mul bx
    add ax, [bp+8]
    mov di, ax

    mov si, [bp+12]        ; puntero al bitmap

    mov ax, [bp+4]         ; width
    mov bx, 320
    sub bx, ax             ; bx = salto de fila (320 - width)

    mov cx, [bp+6]         ; height

sprite_row_loop:
    push cx
    mov cx, [bp+4]         ; width

sprite_pixel_loop:
    lodsb
    cmp al, 0
    je sprite_skip_pixel
    mov es:[di], al
sprite_skip_pixel:
    inc di
    loop sprite_pixel_loop

    pop cx
    add di, bx
    loop sprite_row_loop

    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    pop bp
    ret 10                 ; limpia los 5 words (10 bytes) que empujó el caller
DrawSprite ENDP

END main